using System; using System.Threading.Tasks; using System.Windows.Input;
namespace PhotoBooth.Admin.UI.Mvvm { public sealed class AsyncCommand:ICommand { readonly Func<object,Task> execute; readonly Func<object,bool> can; bool running; public AsyncCommand(Func<object,Task> execute,Func<object,bool> can=null){this.execute=execute;this.can=can;CommandManager.RequerySuggested+=OnRequery;} void OnRequery(object s,EventArgs e)=>CanExecuteChanged?.Invoke(this,EventArgs.Empty); public bool CanExecute(object p)=>!running&&(can?.Invoke(p)??true); public async void Execute(object p){if(!CanExecute(p))return;running=true;Changed();try{await execute(p);}finally{running=false;Changed();}} public event EventHandler CanExecuteChanged; void Changed()=>CanExecuteChanged?.Invoke(this,EventArgs.Empty); } }
